
import os, uuid, base64
from datetime import datetime
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import HTMLResponse
from pydantic import BaseModel

app = FastAPI(title="MaxShop V7.8 ANCLADO")
app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])
COMERCIOS_ADHERIDOS = {"felipe", "panaderia_pm", "lomitos_lo_mas"}
class PagoRequest(BaseModel):
    user_id: str
    comercio_id: str
    monto_original: float
INDEX_B64 = ""
@app.get("/", response_class=HTMLResponse)
def serve():
    for p in ["index.html", "./index.html", "templates/index.html", "/opt/render/project/src/index.html"]:
        try:
            if os.path.exists(p):
                with open(p,"r",encoding="utf-8") as f:
                    c=f.read()
                    if len(c)>5000:
                        return HTMLResponse(c)
        except:
            continue
    return HTMLResponse(base64.b64decode(INDEX_B64).decode("utf-8"))
@app.get("/api")
def api():
    return {"msg":"MaxShop V7.8 ANCLADO - 0 C$B + 10k bienvenida + 10min timeout + roles en perfil + legal expandido", "anclado":"diseno estructura logica"}
@app.get("/comercios/cercanos")
def cercanos(lat: float, lng: float):
    return {"cercanos": [{"id":"felipe","nombre":"Felipe","promo":"10% C$B","distancia":"20m"},{"id":"panaderia_pm","nombre":"Panadería PM","promo":"10% C$B","distancia":"35m"},{"id":"lomitos_lo_mas","nombre":"Lomitos lo-más","promo":"10% C$B","distancia":"80m"}]}
@app.post("/pago/procesar")
def pagar(req: PagoRequest):
    es = req.comercio_id in COMERCIOS_ADHERIDOS
    monto = req.monto_original
    comision = round(monto*0.017,2)
    csb = round(monto*(0.10 if es else 0.05),2)
    return {"status":"aprobado","transaccion":{"id":str(uuid.uuid4()),"monto_detectado":monto,"es_adherido":es,"comision_1_7_cobrada":comision,"csb_cliente_nuevo":csb,"mensaje_exito":f"Compra exitosa, pagaste ${monto:,.0f}","timestamp":datetime.utcnow().isoformat()}}
